/*
 * UART0 是 openvela 的调试口（CH340 那一路）。两个 OS 同时初始化同一个
 * 16550 的表现是字符互相插队、波特率被对方改掉，而且谁都不报错。
 *
 * 所以 Linux 这边彻底关掉它。Linux 在这一版**没有控制台** —— 它活着的
 * 证据是 openvela 那边 `ampctl status` 的"握手完成"变成"是"：那个信号
 * 只有在 Linux 跑到 rockchip_rpmsg 的 probe、建好两个 virtqueue、填好
 * 接收缓冲之后才会发出来，是一个相当靠后、相当可信的存活判据。
 *
 * 真要看 Linux 的日志，40pin 上还有 UART5_M0（21/23 脚）等几路可以接
 * 第二个 USB-TTL；那属于调试时的可选项，不是这一版的前提。
 */

/*
 * ★ /chosen/bootargs 必须覆盖掉，不能只在 U-Boot 里 setenv bootargs。
 *
 *   rk3576-linux.dtsi 里带着厂商的那一串：
 *
 *     earlycon=uart8250,mmio32,0x2ad40000 console=ttyFIQ0
 *     root=PARTUUID=614e0000-0000 rw rootwait ...
 *
 *   而 U-Boot 的 bootargs_add_dtb_dtbo()（arch/arm/mach-rockchip/board.c）
 *   会把内核 DTB 里的 /chosen/bootargs **追加**到 env 的 bootargs 上。
 *   所以在 U-Boot 提示符下 `setenv bootargs 'panic=0'` 之后，内核实际拿到
 *   的仍然是 `panic=0 ... earlycon=uart8250,mmio32,0x2ad40000 ...`。
 *
 *   那个 earlycon 指向 **UART0**，而 UART0 归 openvela。两个 OS 同时往
 *   同一个 16550 写，表现是字符逐个交错、控制台彻底不可读，而且谁都不
 *   报错。这一条上板踩过：双 OS 跑起来后 openvela 的输出整段消失，
 *   看起来像 openvela 没起来，实际是它的字被 Linux 的 earlycon 冲掉了。
 *
 *   这一版 Linux **不需要控制台**：它是纯计算域，存活判据是 openvela 那边
 *   ampctl status 的"握手完成"（见 amp/OWNERSHIP.md）。真要看 Linux 日志，
 *   用 rk3576-kickpi-k7-amp-dbg.dts 那个变体，它把 UART0 让给 Linux，
 *   但**只能在不启 openvela 的隔离实验里用**。
 *
 *   panic=0：Linux 没有 rootfs，挂载根失败必然 panic。panic=0 让它停住
 *   而不是重启 —— 重启走的是 PSCI SYSTEM_RESET，**会把整片 SoC 连
 *   openvela 一起复位**。AMP 下一侧的"正常错误处理"就是另一侧的灾难。
 */

&chosen {
	/*
	 * ★ clk_ignore_unused / pd_ignore_unused 在 AMP 下是**必需**的，
	 *   不是优化。
	 *
	 *   Linux 在 late_initcall 会跑 clk_disable_unused() 和电源域的
	 *   同一套逻辑：把**没有 Linux 消费者**的时钟和电源域全部关掉。
	 *   而 openvela 用的 UART0、SAI、VOP2、I2C、GMAC、CIF……在 Linux
	 *   眼里全都"没人用"（它们的节点要么被删了、要么 disabled）。
	 *
	 *   于是 Linux 会把 openvela 脚下的时钟一个个抽掉。表现是
	 *   **openvela 在初始化中途任意一行静默停住**（本次是 SAI 之后），
	 *   而 Linux 一切正常 —— 看起来像 openvela 自己的 bug。
	 *
	 *   判据很硬：同一份 openvela、同一个配置，FIT 里不带 Linux 时
	 *   一路跑到 NSH 并稳住；带上 Linux 就死在半路。
	 *
	 *   panic=0：Linux 没有 rootfs，挂根必然 panic。panic=0 让它停住而
	 *   不是重启 —— 重启走 PSCI SYSTEM_RESET，会把整片 SoC 连 openvela
	 *   一起复位。一侧的"正常错误处理"就是另一侧的灾难。
	 */
	/*
	 * clk_ignore_unused / pd_ignore_unused 现在是**兜底**，不是主手段 ——
	 * 主手段是上面 rockchip-amp 节点里声明 openvela 用到的资源。
	 * 留着它们的理由：那张声明表难免漏，而漏掉一项的代价是 openvela
	 * 在某一行静默死掉，排查成本远高于多留几个时钟。
	 */
	bootargs = "panic=0 clk_ignore_unused pd_ignore_unused";
};

&uart0 {
	status = "disabled";
};

/* UART4 接蓝牙模组，归 openvela（CONFIG_16550_UART1_BASE=0x2ad70000）。
 * 内核带 SERIAL_8250_DW=y，不关的话 Linux 会接管这个口。
 */
&uart4 {
	status = "disabled";
};

/*
 * ★ openvela 用的 I2C 总线，Linux 一条都不许碰。
 *
 *   内核带 CONFIG_I2C_RK3X=y，dtsi 里是 okay 的 I2C 控制器它全会接管
 *   （复位、改时钟分频、挂 adapter），不管下面有没有它认识的设备。
 *   2026-09-17 上板：同一份 openvela，单系统下 IMX415 正常出图，
 *   双系统下三个摄像头接口 I2C 全部无应答 → /dev/video0 注册失败 →
 *   界面点"打开相机"没反应。
 *
 *   划分见 amp/OWNERSHIP.md：
 *     i2c1  pmic@23（A72 调压）          → Linux，保留
 *     i2c2  hym8563 RTC、husb311         → openvela
 *     i2c3  es8388 音频                   → openvela
 *     i2c4 / i2c5 / i2c8  imx415         → openvela（摄像头整条链）
 *     i2c7  空                            → 关掉，免得 Linux 占着
 *
151:# CONFIG_BLK_DEV_INITRD is not set
153:CONFIG_INITRAMFS_PRESERVE_MTIME=y
746:CONFIG_DEVTMPFS=y
747:CONFIG_DEVTMPFS_MOUNT=y
748:# CONFIG_DEVTMPFS_SAFE is not set
989:# CONFIG_RPMSG_TTY is not set
1598:CONFIG_VIRTIO=y
/*
 * KICKPI-K7 AMP：哪个镜像跑在哪颗核上。
 *
 * 这份 FIT 是 AMP 的**全部契约**。U-Boot（drivers/cpu/rockchip_amp.c）
 * 读它，按 cpu 属性里的 MPIDR 把核分掉：
 *
 *   cpu = <0x000>  A53 簇 core0 —— 也就是 U-Boot 自己正跑在上面的那颗。
 *                  它是"boot cpu"，U-Boot 不会 PSCI 拉它，而是在最后
 *                  armv8_switch_to_el2() 直接跳进去。openvela 走这条路。
 *   cpu = <0x100>  A72 簇 core0。U-Boot 用 PSCI CPU_ON 把它拉起来跑 Linux。
 *
 * 两个簇里剩下的三颗核**不在这里**：各自的 OS 起来以后自己拉
 * （openvela 的 SMP 走 arm64_cpustart.c，Linux 走它的 DTB）。
 *
 * ★ Linux 的镜像不在这份 FIT 里
 *
 *   rockchip_amp.c 的 load_linux_for_nonboot_cpu() 是去跑 `boot_fit` /
 *   `boot_android`，也就是**走正常启动流程从 boot 分区读**。所以 linux
 *   节点只描述"跑在哪颗核、什么执行状态"，镜像本身在 boot 分区的
 *   boot.img 里（见 amp/linux/ 和 scripts/repack-bootimg.py）。
 *
 * ★ 顺序是 Linux 先起
 *
 *   brought_up_all_amp() 先处理 linux 节点，再处理 loadables，最后才把
 *   当前核送进 openvela。这个顺序是必须的：GIC 的 distributor 归 Linux，
 *   它得先配完，openvela 那边才能带着
 *   CONFIG_ARM64_GICV2_SHARED_DIST=y 接着用。
 *
 * 打包：
 *   mkimage -f amp.its -E -p 0xe00 amp.itb
 */

/dts-v1/;
/ {
	description = "KICKPI-K7 AMP: openvela on A53 cluster, Linux on A72 cluster";
	#address-cells = <1>;

	images {
		openvela {
			description  = "openvela (NuttX) on A53 cluster";
			data         = /incbin/("./openvela-amp.bin");
			type         = "firmware";	/* 必须是 firmware */
			compression  = "none";
			arch         = "arm64";
			cpu          = <0x000>;		/* MPIDR：A53 core0 = 启动核 */
			thumb        = <0>;
			hyp          = <0>;		/* EL1。NuttX 自己会降到 EL1 */
			load         = <0x4a400000>;	/* = CONFIG_RAM_START */
			hash {
				algo = "sha256";
			};
		};
	};

	configurations {
		default = "conf";
		conf {
			description = "openvela + Linux";
			loadables = "openvela";

			/*
			 * Linux 跑 A72 簇 core0。地址由 U-Boot 的
			 * kernel_addr_r / fdt_addr_r / ramdisk_addr_r 决定，
			 * 这里给 load 会覆盖 kernel_addr_r。
			 */
			linux {
				description  = "Linux on A72 cluster";
				arch         = "arm64";
				cpu          = <0x100>;
				thumb        = <0>;
				hyp          = <0>;
				/* ★ 越小越好：这段延时全部落在"Linux 已经在跑、
				 * U-Boot 还没跳进 openvela"这个窗口里，而
				 * Linux 的页分配器随时可能动到 U-Boot 占的
				 * 内存。DTB 里已经把那一段 reserved 掉，这里
				 * 再把窗口压到最短，两层一起防。
				 */
				udelay       = <0>;
			};
		};
	};
};
