    memset(&binfo, 0, sizeof(binfo));
    if (ioctl(fd, AUDIOIOC_GETBUFFERINFO, (unsigned long)&binfo) < 0)
      {
        /* 驱动没实现查询：退回自己的默认值，nbuffers 仍是 0，
         * 后面的指针校验会挡住，不会崩。
