  for (i = 0; i < nbuf; i++)
    {
      memset(&buf_desc, 0, sizeof(buf_desc));
      buf_desc.numbytes = bufbytes;
      buf_desc.u.pbuffer = &bufs[i];

      /* ★ 只判负值。AUDIOIOC_ALLOCBUFFER 的返回值约定在不同下半部实现里
