  bool         istx      = (cfg->direction == DMA_MEM_TO_DEV);
  uint8_t      peri      = (uint8_t)(istx ? cfg->dst_drq : cfg->src_drq);

  width = istx ? cfg->dst_width : cfg->src_width;
