  pcm = pcm_decode_initialize(codec);
  if (pcm == NULL)
    {
      syslog(LOG_ERR, "ERROR: PCM 解码层初始化失败\n");
      return -ENODEV;
    }

  ret = audio_register("pcm0", pcm);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: 注册 /dev/audio/pcm0 失败: %d\n", ret);
