      assist_bubble(true, shown);
    }

  g_agent_busy = true;
  g_agent_started = time(NULL);
  lv_obj_remove_flag(g_assist_spinner, LV_OBJ_FLAG_HIDDEN);
  assist_state("拍照、看图中…");
}

