static void init_display_buffer(ulong base)
{
	memory_start = ALIGN(base + DRM_ROCKCHIP_FB_SIZE, align_size);
	memory_end = memory_start;
	cubic_lut_memory_start = ALIGN(memory_start + MEMORY_POOL_SIZE, align_size);
